      for (const r of norm.rows) if (r.cents !== null) sums[r.currency] = (sums[r.currency] || 0) + r.cents;
      for (const [c, v] of Object.entries(norm.trailer.sums)) if (v !== (sums[c] || 0)) problems.push('trailer ' + c + ' sum ' + v + ' cents, read ' + (sums[c] || 0));
